function kebabKeys(obj) {
  const result = {};
  for (const key in obj) {
    if (!Object.prototype.hasOwnProperty.call(obj, key)) continue;
    const kebab = key.replace(/([a-z])([A-Z])/g, "$1-$2").toLowerCase();
    result[kebab] = obj[key];
  }
  return result;
}
